import glob,json,os,re,subprocess,sys
h=subprocess.run([sys.executable,'mangsang.py','--help'],capture_output=True,text=True).stdout
subs=set(re.search(r'\{([a-z,]+)\}',h).group(1).split(','))
bad=[]
adapters={}
for p in sorted(glob.glob('commands/*.md')):
    t=open(p,encoding='utf-8').read(); m=re.search(r'^!`python3 "\$\{CLAUDE_PLUGIN_ROOT\}/mangsang.py" ([a-z]+) \$ARGUMENTS --target \.`$',t,re.M)
    if not m: bad.append((p,'no engine line')); continue
    adapters[os.path.basename(p)[:-3]]=m.group(1)
    if m.group(1)!=os.path.basename(p)[:-3] or m.group(1) not in subs: bad.append((p,m.group(1)))
r=open('README.md',encoding='utf-8').read()
heads=set(re.findall(r'^### `/mangsang:([a-z]+)`',r,re.M))
if heads!=set(adapters): bad.append(('README adapter headings vs commands/', sorted(heads^set(adapters))))
cli_only=subs-set(adapters)
if cli_only!={'move'} or '### `move` (Python CLI)' not in r: bad.append(('CLI-only commands', sorted(cli_only)))
for p in ('plugin.json','.claude-plugin/plugin.json','.codex-plugin/plugin.json'):
    s=json.load(open(p)).get('skills')
    if s is not None and not os.path.isfile(os.path.join(s,'operate','SKILL.md')): bad.append((p,'skills',s))
print('subcommands',sorted(subs)); print('adapters',len(adapters),'cli-only',sorted(cli_only)); print(bad or 'command docs, adapters and skill paths agree'); sys.exit(bool(bad))

import ast,os,shutil,subprocess,sys,tempfile
local={'anchors','hostcall','mangsang','judge_worker'}
bad=[]
for f in ('mangsang.py','anchors.py','judge_worker.py','hostcall.py'):
    for n in ast.walk(ast.parse(open(f,encoding='utf-8').read())):
        mods=[a.name for a in n.names] if isinstance(n,ast.Import) else [n.module] if isinstance(n,ast.ImportFrom) and n.level==0 else []
        for m in mods:
            top=m.split('.')[0]
            if top not in sys.stdlib_module_names and top not in local: bad.append((f,m))
files=subprocess.run(['git','ls-files'],capture_output=True,text=True).stdout.split()
d=tempfile.mkdtemp(prefix='mangsang-standalone-')
for f in files:
    os.makedirs(os.path.join(d,os.path.dirname(f)),exist_ok=True); shutil.copy2(f,os.path.join(d,f))
for argv in (['mangsang.py','--help'],['judge_worker.py','--help']):
    r=subprocess.run([sys.executable,'-E','-s',*argv],cwd=d,capture_output=True,text=True)
    if r.returncode: bad.append((argv,r.stderr[-300:]))
r=subprocess.run([sys.executable,'-E','-s','-c','import mangsang,sys; print(mangsang.engine())'],cwd=d,capture_output=True,text=True)
print(sys.version.split()[0], 'copied', len(files), 'tracked files; engine in copy:', r.stdout.strip() or r.stderr[-200:])
shutil.rmtree(d)
if r.returncode or not r.stdout.startswith('mangsang 2.0.0'): bad.append(('engine stamp', r.stdout.strip()))
print(bad or 'stdlib-only imports; runs from a bare copy of the tracked files'); sys.exit(bool(bad))

import os,re,sys
def slug(h): return re.sub(r'[^\w\- ]','',h.strip().lower().replace('`','')).replace(' ','-')
def heads(p): return {slug(m.group(1)) for m in re.finditer(r'^#+ +(.*)$',open(p,encoding='utf-8').read(),re.M)}
bad=[]
for doc in ('README.md','AGENTS.md','skills/operate/SKILL.md'):
    base=os.path.dirname(doc)
    for t in re.findall(r'\]\(([^)\s]+)\)',open(doc,encoding='utf-8').read()):
        if re.match(r'https?:',t): continue
        path,_,anchor=t.partition('#'); target=os.path.normpath(os.path.join(base,path)) if path else doc
        if not os.path.exists(target): bad.append((doc,t,'missing file')); continue
        if anchor and target.endswith('.md') and anchor not in heads(target): bad.append((doc,t,'missing anchor'))
print(bad or 'links and anchors resolve'); sys.exit(bool(bad))

